+// outputKeepBytes is how many bytes of each end a shortened tool output keeps.
+const outputKeepBytes = 2048
+
+// shortenOutput keeps the first and the last outputKeepBytes bytes of text (each cut at a
+// character boundary) with one line between them that states how many bytes were omitted.
+func shortenOutput(text string) string {
+	head := outputKeepBytes
+	for head > 0 && !utf8.RuneStart(text[head]) {
+		head--
+	}
+	tail := len(text) - outputKeepBytes
+	for tail < len(text) && !utf8.RuneStart(text[tail]) {
+		tail++
+	}
+	return text[:head] + fmt.Sprintf("\n[kogen: %d bytes omitted from the middle of this output]\n", tail-head) + text[tail:]
+}
